/**
 * Case studies. All copy is taken verbatim from 01_REFERENCE.pdf (Ahmed Ibrahim Portfolio 2026).
 * Reorder by changing ORDER at the bottom. Media ids refer to src/data/media.json
 * (generated by scripts/media/build_media.py from scripts/media/images.json).
 */

export type Block = { label: string; text: string; lead?: string };
export type Frame = {
  id: string;
  /** full: edge to edge · wide: inside the grid · half: one of a pair · inset: smaller, offset · tall: portrait column */
  layout: 'full' | 'wide' | 'half' | 'inset' | 'tall';
  alt: string;
};
export type Chapter = { label: string; frames: Frame[] };
export type Tone = { bg: string; ink: string; accent: string; dim: string };

export type Project = {
  slug: string;
  title: string;
  track: 1 | 3;
  trackName: string;
  kind: string; // tiny metadata under the title in indexes
  tagline: string;
  statement?: [string, string]; // two-tone display statement (art direction)
  credits?: string;
  year?: string;
  cover: string;
  preview: string; // image used for pointer previews
  blocks: Block[];
  notes?: Block[];
  chapters: Chapter[];
  tone: Tone;
  interaction?: 'valu' | 'nescafe' | 'spotify';
};

const F = (id: string, layout: Frame['layout'], alt: string): Frame => ({ id, layout, alt });

