export const ORDER = ['shafaq', 'shaheq', 'mtmh', 'myz', 'northbridge', 'valu', 'nescafe', 'spotify'];
export const BRAND = ORDER.filter((s) => PROJECTS[s].track === 1).map((s) => PROJECTS[s]);
export const ART = ORDER.filter((s) => PROJECTS[s].track === 3).map((s) => PROJECTS[s]);

export function nextOf(slug: string): Project {
  const i = ORDER.indexOf(slug);
  return PROJECTS[ORDER[(i + 1) % ORDER.length]];
}
export function indexOf(slug: string): { n: number; of: number } {
  const p = PROJECTS[slug];
  const list = p.track === 1 ? BRAND : ART;
  return { n: list.findIndex((x) => x.slug === slug) + 1, of: list.length };
}
